result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "registry.py", "content": """"Event-sourced immunization registry -- stdlib only.

Event log: append-only JSON Lines file. Exactly one event per line, so
physical line number == event ordinal (1-based).

Event types
-----------
DoseRecorded     {patient, date, lot}
DoseInvalidated  {patient, dose_index, reason}
PatientMerged    {from_id, into_id}

Projections are rebuilt *purely* by folding events. A snapshot taken at
event N plus the tail N..end must serialize identically to a full replay.
"""

import json
import os

EVENT_TYPES = ("DoseRecorded", "DoseInvalidated", "PatientMerged")
SNAPSHOT_EVERY = 100


class RegistryError(ValueError):
    """Any corruption, protocol violation or impossible operation."""


def resolve(merge_map, pid):
    """Follow merged-identity links transitively (A->B->C => A resolves to C)."""
    seen = set()
    while pid in merge_map:
        if pid in seen:  # defensive; cycles are rejected at merge time
            raise RegistryError(f"merge cycle detected while resolving {pid!r}")
        seen.add(pid)
        pid = merge_map[pid]
    return pid


class Projection:
    """Fold state: valid doses per patient, per-lot counts, merge map."""

    def __init__(self):
        # canonical patient id -> list of {"date", "lot", "valid"} in record order
        self.doses = {}
        # lot -> number of *valid* administrations (invalidation decrements)
        self.lot_counts = {}
        # from_id -> into_id (acyclic by construction)
        self.merge_map = {}

    # ------------------------------------------------------------------ fold

    def apply(self, event, line_no=None):
        where = f"line {line_no}: " if line_no is not None else ""
        try:
            etype = event["type"]
        except TypeError:
            raise RegistryError(f"{where}event is not an object: {event!r}")

        if etype == "DoseRecorded":
            pid = resolve(self.merge_map, event["patient"])
            self.doses.setdefault(pid, []).append(
                {"date": event["date"], "lot": event["lot"], "valid": True}
            )
            self.lot_counts[event["lot"]] = self.lot_counts.get(event["lot"], 0) + 1

        elif etype == "DoseInvalidated":
            pid = resolve(self.merge_map, event["patient"])
            idx = event["dose_index"]
            bucket = self.doses.get(pid)
            if bucket is None or not 0 <= idx < len(bucket):
                raise RegistryError(
                    f"{where}dose_index {idx} out of range for patient {pid!r}"
                )
            dose = bucket[idx]
            if dose["valid"]:
                dose["valid"] = False
                self.lot_counts[dose["lot"]] -= 1
            # The event itself stays in the log forever; only the fold changes.

        elif etype == "PatientMerged":
            src, dst = event["from_id"], event["into_id"]
            if src == dst:
                raise RegistryError(f"{where}cannot merge {src!r} into itself")
            if src in self.merge_map:
                raise RegistryError(
                    f"{where}{src!r} was already merged into "
                    f"{self.merge_map[src]!r}; cannot re-merge"
                )
            # Cycle guard: adding src->dst is illegal iff src is reachable
            # from dst via existing edges (e.g. A->B->C, then C into A).
            cur = dst
            while cur in self.merge_map:
                if cur == src:
                    raise RegistryError(
                        f"{where}merging {src!r} into {dst!r} would create a "
                        f"merge cycle"
                    )
                cur = self.merge_map[cur]
            self.merge_map[src] = dst
            canon = resolve(self.merge_map, dst)
            if src in self.doses:
                self.doses.setdefault(canon, []).extend(self.doses.pop(src))

        else:
            raise RegistryError(f"{where}unknown event type: {etype!r}")

        # Surface missing fields uniformly with a line number.
        for req in () :
            pass

    # --------------------------------------------------------- serialization

    def to_dict(self):
        """Canonical, JSON-friendly form (valid doses only)."""
        return {
            "valid_doses": {
                pid: [{"date": d["date"], "lot": d["lot"]} for d in bucket if d["valid"]]
                for pid, bucket in self.doses.items()
            },
            "lot_counts": dict(self.lot_counts),
            "merge_map": dict(self.merge_map),
        }

    @classmethod
    def from_dict(cls, data):
        proj = cls()
        for pid, doses in data["valid_doses"].items():
            proj.doses[pid] = [
                {"date": d["date"], "lot": d["lot"], "valid": True} for d in doses
            ]
        proj.lot_counts = dict(data["lot_counts"])
        proj.merge_map = dict(data["merge_map"])
        return proj

    def serialize(self) -> bytes:
        """Deterministic bytes: sorted keys, compact separators."""
        return json.dumps(
            self.to_dict(), sort_keys=True, separators=(",", ":")
        ).encode("utf-8")

    # ------------------------------------------------------------ accessors

    def valid_dose_count(self, pid):
        """Valid-dose count for a patient, through any merge chain."""
        canon = resolve(self.merge_map, pid)
        return sum(1 for d in self.doses.get(canon, ()) if d["valid"])


class EventLog:
    """Append-only JSONL event store with periodic snapshots."""

    def __init__(self, path):
        self.path = str(path)
        self.events = []
        if os.path.exists(self.path):
            with open(self.path, "r", encoding="utf-8") as fh:
                for line_no, line in enumerate(fh, 1):
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        event = json.loads(line)
                    except json.JSONDecodeError as exc:
                        raise RegistryError(
                            f"line {line_no}: invalid JSON ({exc})"
                        )
                    if not isinstance(event, dict) or "type" not in event:
                        raise RegistryError(f"line {line_no}: malformed event")
                    self.events.append(event)

    # ---------------------------------------------------------------- append

    def append(self, event):
        if not isinstance(event, dict) or event.get("type") not in EVENT_TYPES:
            bad = event.get("type") if isinstance(event, dict) else event
            raise RegistryError(f"unknown event type: {bad!r}")
        with open(self.path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(event, sort_keys=True) + "\n")
        self.events.append(event)  # log only ever grows
        if len(self.events) % SNAPSHOT_EVERY == 0:
            self._write_snapshot(len(self.events))

    # -------------------------------------------------------------- snapshots

    @property
    def snapshot_dir(self):
        return self.path + ".snapshots"

    def _write_snapshot(self, count):
        os.makedirs(self.snapshot_dir, exist_ok=True)
        proj = self.replay_full()
        payload = {"event_count": count, "projection": proj.to_dict()}
        final = os.path.join(self.snapshot_dir, f"snapshot_{count:06d}.json")
        tmp = final + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, sort_keys=True)
        os.replace(tmp, final)

    def _latest_snapshot(self):
        """Newest snapshot whose event_count fits inside the current log."""
        best = None
        if os.path.isdir(self.snapshot_dir):
            for name in os.listdir(self.snapshot_dir):
                if name.startswith("snapshot_") and name.endswith(".json"):
                    n = int(name[len("snapshot_"):-len(".json")])
                    if n <= len(self.events) and (best is None or n > best[0]):
                        best = (n, os.path.join(self.snapshot_dir, name))
        return best

    # ---------------------------------------------------------------- replay

    def replay_full(self):
        proj = Projection()
        for line_no, event in enumerate(self.events, 1):
            proj.apply(event, line_no=line_no)
        return proj

    def replay_from_snapshot(self):
        """Rebuild from latest snapshot + tail; must equal replay_full()."""
        found = self._latest_snapshot()
        if found is None:
            return self.replay_full()
        count, snap_path = found
        with open(snap_path, "r", encoding="utf-8") as fh:
            snap = json.load(fh)
        if snap["event_count"] != count:
            raise RegistryError(f"snapshot {snap_path}: corrupted event_count")
        proj = Projection.from_dict(snap["projection"])
        for line_no in range(count, len(self.events)):
            proj.apply(self.events[line_no], line_no=line_no + 1)
        return proj
